pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Only test with non-zero newOwner (the reference requires this)
        vm.assume(newOwner != address(0));
        // Pre-condition: set owner to msg.sender so the modifier passes
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // Trigger the owned() function
        vm.prank(newOwner);
        c.owned();
        // Assert owner is not zero
        assertTrue(c.owner() != address(0));
    }
}

